local function QueueModelFrame(model)
    local row = model.frame
    local list = row and row.aprVirtualList
    if not list or not list.renderBudgetMs then return false end
    -- Published dense rows use the same budget when their state/details change.
    -- Mutating hundreds of font strings inline would bypass viewport scheduling.
    row.boundGeneration = nil
    list:RefreshVisible()
    return true
end--[[APR_DIAG]]; QueueModelFrame = APRTrace("APR-Core/ui/route/QuestOrderListSupport.lua:87:QueueModelFrame#6", QueueModelFrame)--[[/APR_DIAG]]

function APR.questOrderListSupport:SetStepFrameState(container, color, isCurrentStep, checkpoint)
    if not container then return end
    if container.isModel then
        local changed = container.color ~= color or container.isActiveStep ~= isCurrentStep
        container.color, container.isActiveStep = color, isCurrentStep
        if changed and container.frame and not QueueModelFrame(container) then
            self:SetStepFrameState(container.frame, color, isCurrentStep)
        end
        return
    end

    local titleRole = isCurrentStep and "activeStep" or (color == "green" and "success" or "muted")
    APR:SetFontStringRole(container.indexFont, titleRole)
    APR:SetFontStringRole(container.titleFont, titleRole)
    for _, questFont in ipairs(container.questFonts or {}) do
        APR:SetFontStringRole(questFont, isCurrentStep and "base" or "muted")
        if checkpoint then checkpoint() end
    end
end--[[APR_DIAG]]; APR.questOrderListSupport.SetStepFrameState = APRTrace("APR-Core/ui/route/QuestOrderListSupport.lua:98:APR.questOrderListSupport:SetStepFrameState#7", APR.questOrderListSupport.SetStepFrameState)--[[/APR_DIAG]]

function APR.questOrderListSupport:CollapseStepDetails(container)
    if container and container.isModel then
        local changed = #container.questInfo > 0
        container.questInfo = {}
        if changed and container.frame and not QueueModelFrame(container) then self:CollapseStepDetails(container.frame) end
        return changed
    end
    if not container or not container.questFonts or #container.questFonts == 0 then
        return false
    end

    for _, questFont in ipairs(container.questFonts) do
        questFont:Hide()
    end
    container.questFonts = {}
    container:SetScript("OnEnter", nil)
    container:SetScript("OnLeave", nil)
    container:EnableMouse(false)
    if GameTooltip:GetOwner() == container then GameTooltip:Hide() end
    return true
end--[[APR_DIAG]]; APR.questOrderListSupport.CollapseStepDetails = APRTrace("APR-Core/ui/route/QuestOrderListSupport.lua:118:APR.questOrderListSupport:CollapseStepDetails#8", APR.questOrderListSupport.CollapseStepDetails)--[[/APR_DIAG]]

